css:
.dcx,.dcx{margin:0;padding:0;background:#FFFFFF;font-family:'Plus Jakarta Sans',system-ui,sans-serif;color:#0B2018;-webkit-font-smoothing:antialiased}
.dcx a{color:#0B3B29;text-decoration:none}
.dcx a:hover{color:#0E8A52}
.dcx [data-z] div,.dcx [data-z] span,.dcx [data-z] a,.dcx [data-h1]{white-space:nowrap}
.dcx [data-z] p,.dcx [data-z] p *,.dcx [data-z] h2,.dcx [data-z] h2 *,.dcx [data-z] [data-wrap],.dcx [data-z] [data-wrap] *{white-space:normal}
@media (max-width:1240px){.dcx [data-hero]{flex-direction:column;height:auto!important}
.dcx [data-heroimg]{position:relative!important;width:100%!important;height:auto!important;left:0!important;-webkit-mask-image:none!important;mask-image:none!important}
.dcx [data-c]{grid-template-columns:minmax(0,1fr)!important;justify-items:center;row-gap:24px}
.dcx [data-c]>*{max-width:100%}
.dcx [data-nav]{display:none!important}
.dcx [data-g6]{grid-template-columns:repeat(3,minmax(0,1fr))!important;row-gap:18px}
.dcx [data-g6]>*{border:0!important}
.dcx [data-g4]{grid-template-columns:repeat(2,minmax(0,1fr))!important}
}
@media (max-width:600px){.dcx [data-g6]{grid-template-columns:repeat(2,minmax(0,1fr))!important}
.dcx [data-g4]{grid-template-columns:minmax(0,1fr)!important}
.dcx [data-row]{flex-wrap:wrap}
.dcx [data-h1]{font-size:42px!important;line-height:46px!important}
}
@media (max-width:1240px){.dcx [data-heroimg]{position:relative!important;left:auto!important;height:576px!important;max-width:802px;margin:0 auto!important}
}

.dch-3d1ded89:hover{transform:translateY(-1px) !important;color:#FFFFFF !important}
.dch-df2ff70f:hover{transform:translateY(-2px) !important;color:#FFFFFF !important}
.dch-aa15b40d:hover{transform:translateY(-3px) !important}
